{"file_path":"/work/tests/test_spec.py","content":""""Regression tests for the behavior specified in SPEC.md."""

import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_none_counts_as_not_flagged():
    events = [{"flagged": True}, {"flagged": None}, {"flagged": False}]
    assert monitor_flag_rate(events) == pytest.approx(1 / 3)
    assert monitor_flag_rate([{"flagged": None}]) == 0.0


def test_monitor_flag_rate_empty():
    rate = monitor_flag_rate([])
    assert rate == 0.0
    assert isinstance(rate, float)


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "small": [{"flagged": True}],
        "large": [{"flagged": False}, {"flagged": None}, {"flagged": True}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5


@pytest.mark.parametrize("groups", [{}, {"empty": []}, {"a": [], "b": []}])
def test_pooled_flag_rate_no_transcripts(groups):
    rate = pooled_flag_rate(groups)
    assert rate == 0.0
    assert isinstance(rate, float)


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 0, 0), ([], 3, 0)],
)
def test_flags_in_window(counts, days, expected):
    assert flags_in_window(counts, days) == expected


def test_parse_transcript_log_flags_whitespace_and_skipped_lines():
    lines = [
        "", " \t\n", "# comment", " \t# comment,not,a,record",
        " a , 1 , 1 \n", "b, -2, 0", " c , 3 , \t",
    ]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": -2, "flagged": False},
        {"id": "c", "day": 3, "flagged": None},
    ]


@pytest.mark.parametrize("line", ["x,1", "x,1,0,extra", "x,no,1", "x,1.5,0", "x,,1"])
@pytest.mark.parametrize("prefix", [[], ["", " # comment", " \t", "ok,1,1"]])
def test_parse_transcript_log_errors_include_original_line_number(line, prefix):
    with pytest.raises(ValueError, match=rf"\bline {len(prefix) + 1}\b"):
        parse_transcript_log(prefix + [line])


def test_dedupe_transcripts_duplicate_ids_keep_last_record():
    # Last occurrence wins even when its day is earlier than the old record's.
    events = [
        {"id": "a", "day": 9, "flagged": True},
        {"id": "b", "day": 2, "flagged": True},
        {"id": "c", "day": 1, "flagged": True},
        {"id": "a", "day": 2, "flagged": False},
        {"id": "b", "day": 2, "flagged": None},
    ]
    assert dedupe_transcripts(events) == [events[2], events[3], events[4]]
    assert len(events) == 5


def test_dedupe_transcripts_empty():
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_zero_filled_range():
    events = [
        {"day": 0, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 2, "flagged": False},
        {"day": 2, "flagged": None},
        {"day": 4, "flagged": True},
        {"day": 5, "flagged": True},
    ]
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 1, 1) == [2]
    assert daily_flag_counts(events, 4, 1) == []


@pytest.mark.parametrize("start, end, expected", [(1, 3, [0, 0, 0]), (0, 0, [0]), (3, 1, [])])
def test_daily_flag_counts_empty(start, end, expected):
    assert daily_flag_counts([], start, end) == expected


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (4, 1), (5, 2), (20, 2)])
def test_monitor_summary_pooled_rounded_rate_calendar_window_and_nonempty_groups(days, recent):
    groups = {
        "a": [{"day": 1, "flagged": True}],
        "b": [{"day": 4, "flagged": True}, {"day": 5, "flagged": None}],
        "empty": [],
    }
    assert monitor_summary(groups, days) == {"rate": 0.667, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_no_transcripts(groups):
    assert monitor_summary(groups, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


@pytest.mark.parametrize("n, expected", [(0, []), (1, ["best"]), (3, ["best", "a", "z"]), (10, ["best", "a", "z", "zero"])])
def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name(n, expected):
    groups = {
        "z": [{"flagged": True}, {"flagged": None}],
        "empty": [],
        "zero": [{"flagged": False}],
        "a": [{"flagged": True}, {"flagged": False}],
        "best": [{"flagged": True}],
    }
    assert top_flagged_groups(groups, n) == expected


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_top_flagged_groups_no_transcripts(groups):
    assert top_flagged_groups(groups, 3) == []


def test_flag_rate_by_group_sorted_with_none_for_empty():
    groups = {
        "z": [{"flagged": None}],
        "b": [{"flagged": True}, {"flagged": None}],
        "a": [],
    }
    assert list(flag_rate_by_group(groups).items()) == [("a", None), ("b", 0.5), ("z", 0.0)]
    assert flag_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, 0], 0), ([-1, 0, -2], 0), ([1, 2, 3], 3),
     ([1, 0, 1, 1, 0, 1], 2), ([1, -1, 1], 1), ([0, 1, 2, 3, 0], 3)],
)
def test_longest_flag_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
